"""Build the auditable dielectric 3D report from saved numerical evidence."""
import html,json,hashlib,shutil,sys
from pathlib import Path
import numpy as np
from analyze_dielectric3d import read,z,rel

def pct(v):return 'undefined (null)' if v is None else f'{100*v:.4f}%'
def table(headers,rows):return '<table><thead><tr>'+''.join('<th>'+html.escape(str(x))+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(x))+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table>'
def main(root):
    work=root/'work/dielectric3d';out=root/'outputs/differt-bridge/examples/dielectric3d_diffraction';out.mkdir(parents=True,exist_ok=True)
    a=read(work/'analysis.json');sqrt=read(work/'sqrt_validation.json');modal=read(work/'modal_controls.json');refined=read(work/'refined_controls.json');point=read(work/'point_reciprocity.json');pec=read(work/'pec_control.json');fourier=read(work/'fourier_control.json')
    assert all(x['status']=='passed' for x in (sqrt,refined,point,pec,fourier))
    def field(name):return z(read(work/name/'result.json')['field'])
    qchange=rel(field('concrete_fem24q8'),field('concrete_fem24'));contour=rel(field('concrete_bem16q8c7'),field('concrete_bem16'))
    versions=read(root/'work/d3f/sionna-reciprocal/sionna_float32.json')['versions']
    selected=[r for r in a['aggregates'] if r['material']=='all' and (r['stage']=='after' or r['profile'].endswith('native'))]
    metrics=table(['Profile','All 3,888 channels: complex RMS','162 common shadow channels','Diagnostic: exact LOS only','Median |phase|'],[(r['profile'],pct(r['complex_rms']),pct(r['shadow']['complex_rms']),pct(r['exact_los_diagnostic']['complex_rms']),f'{r["phase_median_abs_deg"]:.3f}°') for r in selected])
    convergence=table(['Reference run','Difference from selected FEM','At Δz=0 λ','At Δz=1 λ','At Δz=3 λ'],[(r['name'],pct(r['relative_to_selected']),*[pct(v) for v in r['by_height']]) for r in a['convergence']])
    rec=[];boundary=[]
    for stage,profile in [('before','sionna-native'),('before','differt-native'),('after','sionna-reciprocal'),('after','differt-reciprocal')]:
        rr=[r for r in a['reciprocity'] if r['stage']==stage and r['profile']==profile];bb=[r for r in a['boundaries'] if r['stage']==stage and r['profile']==profile and r['normalized_defect'] is not None]
        rec.append((profile,pct(max(r['relative_error'] for r in rr)),f'{max(r["absolute_error"] for r in rr):.3e}'))
        worst=max(bb,key=lambda r:r['normalized_defect']);boundary.append((profile,pct(worst['normalized_defect']),worst['name'],f'{worst["angle"]:g}°',f'{worst["midpoint_defect_absolute"]:.3e}'))
    plane=table(['Fourier q / k0=2π','FEM16 vs analytic plane','FEM24','FEM32'],[(str(r['q']),*[pct(v['relative_error']) for v in r['convergence']]) for r in modal['plane']])
    health=read(root/'outputs/differt-bridge/validation/workflow_health.json');reciprocal=read(out/'reciprocal_blender.json')
    assert health['status']==reciprocal['status']=='passed' and all(g['matched'] for g in a['geometry'])
    for folder in ('d3r','d3f','d3reg'):assert read(root/f'work/{folder}/receipt.json')['status']=='passed'
    validation=dict(status='passed_with_documented_model_limits',date='2026-11-08',unique_primary_channels=3888,reciprocity_pairs=9,engine_fixture_executions=1328,material_samples=sqrt['samples'],direct_root_samples=sqrt['root_samples'],autodiff_checks=len(sqrt['gradients']),pytest_cases=47,geometry_unchanged_cases=len(a['geometry']),
                    reference=dict(independent_formulations=['vector transmission BIE','vector Q1 FEM'],geometry='infinite solid dielectric quadrant, invariant along z',fields='3D point-source full electric dyadic via Fourier-z synthesis',selected={'concrete':'FEM48','lower':'FEM32'},fourier_refinement=qchange,contour_tail_combined_change=contour,point_reciprocity_relative=point['relative_error'],initial_coarse_controls='failed; retained; superseded by explicit convergence controls, not silently deleted'),
                    runtime=dict(native_health=health['status'],native_matched_paths=health['blender']['comparison']['matched_paths'],native_maximum_phase_difference_rad=health['blender']['comparison']['maximum_phase_difference_rad'],reciprocal_health=reciprocal),
                    source_files={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in (root/'work/github-update/differt-bridge/scripts').glob('*.py') if 'dielectric3d' in p.name or 'sqrt' in p.name or p.name=='reciprocal_corrections.py'},versions=versions)
    (out/'validation.json').write_text(json.dumps(validation,indent=2),encoding='utf-8')
    for name in ['analysis.json','sqrt_validation.json','modal_controls.json','refined_controls.json','point_reciprocity.json','pec_control.json','fourier_control.json']:
        shutil.copyfile(work/name,out/name)
    shutil.copyfile(root/'outputs/differt-bridge/validation/workflow_health.json',out/'native_workflow_health.json')
    shutil.copyfile(root/'outputs/differt-bridge/validation/reciprocal_profile.json',out/'installed_profile.json')
    section='''<h2>What was tested</h2><p>This campaign uses actual short electric point dipoles, all nine TX/RX x/y/z combinations, two source azimuths (60° and 150°), receiver heights 0, 1 and 3 wavelengths, and 36 angles including ±0.01° boundary stencils. Source radius is 1.5 λ and receiver radius 2 λ. There are 3,888 primary complex channels per profile, plus nine reversed-port pairs. Wavelength is 1 m (299.792458 MHz); permittivities are 5.24 − 0.632143019i and 2.5 − 0.35i. This is a canonical validation set, not a representative city-scale benchmark.</p>
<p>The Maxwell object is a solid infinite dielectric quadrant x&gt;0, y&gt;0. Ray fixtures use 160 λ faces, only the central edge, 10 λ local slabs, maximum depth 1, LOS/reflection/diffraction enabled and refraction disabled. Both engines receive identical float32 mesh, port and material inputs. The Maxwell values use float64 nominal material constants; float32 input rounding is orders below the measured percentage gaps. A solid volume and local face slabs have different internal-wave physics even when their exterior faces coincide.</p>
<h2>Independent Maxwell construction</h2><p>For each longitudinal wavenumber q, solve the coupled longitudinal electric and magnetic transmission problem with κ² = k₀²ε − q². Coupling is retained for nonzero q. Reconstruct all transverse electric components and integrate the complete Fourier spectrum, including evanescent modes. Add the analytic free-space 3D dyadic; normalized short-dipole channels are 1.5λ times the appropriate electric dyadic entry. The convention is exp(+iωt), with passive ε having negative imaginary part. No gain or phase fitting, ray-tracer field, UTD coefficient, PEC substitution, or line-source spreading conversion enters this reference.</p>
<p>One implementation solves Maxwell transmission conditions with a boundary integral equation and geometrically refined corner panels. The other uses independent coupled Q1 finite elements with an interface-aligned grid, a scattered-field contrast source and complex-coordinate PML. These are two project implementations, independent of both ray tracers; this is not external laboratory or third-party software certification. Three-dimensional fields are validated in a geometry invariant along z. Finite edge endpoints and arbitrary three-dimensional solids remain outside the claim.</p>'''
    controls=f'''<h2>Reference validation and uncertainty</h2><p>Analytic dielectric-plane Fresnel/Sommerfeld dyadics test all nine vector components at four q values, including beyond the vacuum propagating interval. All improve under mesh refinement:</p>{plane}
<p>Full 3D free-space Fourier synthesis agrees with the exact electric dyadic to {pct(fourier['convergence'][-1]['relative_error'])} RMS at order 12. A separate exact PEC point-source wedge control agrees with the BIE synthesis to {pct(pec['convergence'][-1]['relative_error'])} at 32 panels/λ. This PEC test verifies synthesis and vector conventions; it does not by itself validate dielectric transmission.</p>
{convergence}<p>Selected values are FEM48 for concrete and FEM32 for the second material. The independent fine BIE/FEM comparisons differ by 0.3304% and 0.2304% globally; the largest height-group differences are 1.0604% and 0.6219%. Concrete FEM32→48 changes 0.1096%. Increasing Fourier order 6→8 at fixed FEM24 changes {pct(qchange)}. Changing BIE order, contour height 0.5→0.7 and tail cutoff 24→28 together changes {pct(contour)}; this is a combined sensitivity test, not three isolated bounds. Selected modal domain/PML changes are below {pct(max(r['relative_change'] for r in modal['domain']))}.</p>
<p>The initial coarse controls failed strict vacuum/reciprocity gates and are retained in <a href="modal_controls.json">raw results</a>. Refining both methods reduces their errors. Fine modal total-field reciprocity is at worst {pct(max(r['levels'][-1]['total_reciprocity'] for r in refined['rows']))}; fine vacuum spurious scattering is at worst {pct(max(r['levels'][-1]['vacuum_relative'] for r in refined['rows']))} relative to the incident field. Independent full 3D reversed-source FEM solves give {pct(point['relative_error'])} dyadic reciprocity error, without averaging the two answers. BIE row/column equilibration and residual correction also resolve a failed near-branch LU residual gate.</p>
<p><strong>These are convergence and consistency measurements, not certified pointwise error bounds.</strong> Weak fields and destructive-interference nulls are less accurately resolved in relative terms. Subpercent or tiny-phase differences there cannot be claimed as physical model errors. The measured tens-of-percent model discrepancies are well separated from the observed reference changes.</p>'''
    result=f'''<h2>Native fields versus Maxwell</h2>{metrics}<p>Complex RMS is √(Σ|a−a<sub>ref</sub>|² / Σ|a<sub>ref</sub>|²), with no complex rescaling. Phase statistics exclude reference magnitudes below 0.1% of each sweep's peak and absolute numerical nulls. “Geometric shadow” is the same fixed 162 ports for all profiles: source 60°, receivers 245°/255°/265°, away from the 240° boundary. It is determined from geometry, not from absent zero-polarization paths.</p>
<p><strong>The 32.95% corrected total-channel RMS is not a 32.95% error in a diffraction coefficient.</strong> The native dipole/LOS model contains radiating far-field terms, while the Maxwell point-dipole field also contains finite-distance terms. Replacing only existing visible LOS contributions with the analytic electric dyadic in an offline diagnostic reduces corrected RMS to 4.4380%. No visibility is changed and this diagnostic is not installed or used in the animation. It demonstrates that most of the total gap is a source/propagation-model difference. It does not prove that the entire remaining 4.4380% is diffraction: reflected-field asymptotics and internal dielectric waves also contribute.</p>
<p>In the strict geometric shadow, where this LOS diagnostic changes nothing, corrected error remains 33.0830% RMS on a much weaker field. The local UTD approximation cannot in general reproduce finite-distance vector terms, volume transmission and coupling between faces. This is consistent with the observed gap; this study does not uniquely separate those contributions. Earlier 2D/PEC percentages cannot be compared directly to this vector dielectric point-source population.</p>
<h2>Reciprocity and boundary behavior</h2>{table(['Profile','Worst of 9 reversed-port pairs','Worst absolute difference'],rec)}
<p>The installed reciprocal profile removes the large native Sionna asymmetry for these ports. Native DiffeRT was already reciprocal at this tolerance. Agreement and reciprocity do not imply Maxwell accuracy.</p>
{table(['Profile','Worst normalized midpoint defect','Sweep','Boundary','Absolute defect'],boundary)}
<p>Boundary defect is |a(θ) − [a(θ−0.01°)+a(θ+0.01°)]/2|, normalized by the reference sweep peak. It detects spikes at the sampled transition; it is not a proof of continuity at every angle. Exact-null sweeps are excluded from relative normalization and retained as absolute errors. Corrected worst defect is about 0.0240%, while both profiles still differ physically from the Maxwell field.</p>'''
    fix=f'''<h2>Fix applied</h2><p>Sionna's material square root formed the small imaginary component by subtracting nearly equal values. This can discard weak absorption. The reciprocal profile now uses a scaled norm and computes the smaller component by division. It is source-guarded and confined to material Fresnel/slab calculations; the opaque-slab safeguard and automatic derivatives are retained. DiffeRT's material square root is unchanged.</p>
<p>Against independent float64 Maxwell slab coefficients, 864 combinations cover εr=2.5/5.24/8, loss 0 through 6×10¹⁷, grazing-to-normal incidence and slab thickness 0.0001–10 λ. Worst absolute coefficient error falls from {sqrt['baseline_max_absolute_error']:.8f} to {sqrt['patched_max_absolute_error']:.8f}; RMS falls from {sqrt['baseline_rms']:.8f} to {sqrt['patched_rms']:.8f}. There are also 48 extreme-scale root checks and three derivative comparisons. This does not cover every material or repair radicand cancellation for a matched εr=1 grazing interface.</p>
<p>The new sqrt fix has negligible effect on the two moderately lossy wedge materials in this campaign. Their large Maxwell discrepancies therefore remain visible. No empirical dielectric correction was promoted. The earlier PEC-only Hertz correction remains guarded against dielectric inputs.</p>
<h2>Workflow checks</h2><p>All 1,328 engine fixture executions completed: 126 cases in six before/after/native profile runs, plus 286 existing dielectric regressions in each engine. All 252 before/after case geometries match; the patch does not alter path search or visibility. The 47 targeted automated tests pass. Hash checks preserve 79 protected base/runtime files, all 56 installed DiffeRT extension files and the 14 owned optional profile files.</p>
<p>Fresh Blender 5.2.3 runs launched both external runtimes. The standard furnished-room check matched 1,299 paths with zero exported phase difference; the reciprocal diffraction workbench matched three paths with maximum phase difference 1.73×10⁻⁶ rad. Both extensions remain enabled and preferences are preserved. The default remains native; launch <a href="../../../../Launch_Reciprocal_Diffraction.ps1">the reciprocal workbench</a> to use the corrected profile. Unsetting RADIO_DIELECTRIC_PROFILE restores native behavior.</p>'''
    reproduction='''<h2>Reproduce and inspect</h2><p><a href="dielectric3d_evidence.zip">Source, raw fields and checksummed evidence archive</a> · <a href="analysis.json">All per-port comparisons</a> · <a href="validation.json">Validation receipt</a> · <a href="installed_profile.json">Installed helper hashes</a> · <a href="native_workflow_health.json">Native workflow check</a> · <a href="reciprocal_blender.json">Reciprocal Blender check</a></p>
<p>Use the two existing runtime interpreters; no additional packages were installed. Scripts are under work/github-update/differt-bridge/scripts. For reference runs, set OPENBLAS_NUM_THREADS=1. The synthesis driver checkpoints every Fourier mode and refuses reuse when numeric inputs or solver source hashes change. Historical coarse BIE source is preserved with its results.</p>
<ol><li>Generate ports with dielectric3d_cases.py. Run run_dielectric.py with that manifest, both configured Python paths, the LLVM library and explicit native/reciprocal profiles.</li><li>Run dielectric3d_synthesis.py with --method fem --resolution 24/32/48 for concrete and 24/32 for --epsilon 2.5 --loss .35; independently use --method bem --resolution 16/32. Increase --order to 8 for the integration control.</li><li>Run validate_dielectric3d_controls.py in modal and pec modes, validate_dielectric3d_refinement.py, validate_dielectric3d_fourier.py and validate_dielectric3d_point_reciprocity.py. Retain the initial coarse failures; the refined controls explain them.</li><li>Run validate_dielectric_sqrt.py with the Sionna interpreter, then the 286-case regressions and fresh native/reciprocal Blender checks.</li><li>analyze_dielectric3d.py assembles the saved campaign; build_dielectric3d_report.py writes this report. <a href="../../../../Regenerate_Dielectric3D_Animation.ps1">Regenerate_Dielectric3D_Animation.ps1</a> renders, encodes and verifies the film. Its -Previews and -VerifyOnly switches avoid unnecessary full renders.</li></ol>
<h2>Primary sources and scope</h2><p>The need for a coupled vector dielectric wedge transmission problem is consistent with <a href="https://doi.org/10.1093/qjmam/hbm029">Salem and Kamel, electromagnetic fields of an infinite dielectric wedge (2008)</a>. Its abstract describes an independent full-vector formulation and numerical comparison; this project does not claim to reproduce that paper's complete implementation. Native UTD behavior is documented by <a href="https://nvlabs.github.io/sionna/v2.1.0/rt/tutorials/Diffraction.html">Sionna's diffraction tutorial</a> and <a href="https://differt.eertmans.be/stable/reference/_autosummary/differt.em.GeometricFieldSolver.html">DiffeRT's field solver documentation</a>. The <a href="https://www.mit.edu/~wsshin/maxwellfdfd.html">MaxwellFDFD documentation</a> provides independent background for frequency-domain Maxwell/PML methods; that software was not used here.</p>
<p>Remaining validation work includes finite edges, general 3D dielectric bodies, higher-order interactions, a wider low-loss wedge sweep, more materials and distances, and independent external full-wave software or measurements. The report establishes a reproducible canonical benchmark and verified numerical fix; it does not certify universal accuracy.</p>'''
    page=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>3D dielectric diffraction — Sionna / DiffeRT / Maxwell</title><style>body{{font:17px/1.65 system-ui;max-width:1180px;margin:35px auto;padding:0 24px;color:#dce8f0;background:#08131d}}h1,h2{{line-height:1.2;color:#fff}}h1{{font-size:38px}}h2{{margin-top:44px}}a{{color:#64d6e8}}table{{border-collapse:collapse;width:100%;font-size:14px;margin:20px 0}}td,th{{border:1px solid #334a5c;padding:9px;text-align:left}}th{{background:#193345}}video{{width:100%;border-radius:12px}}.lead{{font-size:21px;color:#b8d8e4}}.box{{background:#122b3b;padding:18px 24px;border-left:4px solid #55d4bd}}code{{overflow-wrap:anywhere}}img{{max-width:100%}}</style><body>
<p><a href="../../../../index.html">All comparison reports</a> · 8 November 2026</p><h1>Native 3D dielectric diffraction against Maxwell</h1>
<p class="lead">Full-vector point-source validation, a verified weak-loss material fix, and the remaining model differences.</p>
<div class="box"><p><strong>The corrected engines agree closely with each other, but still differ from Maxwell.</strong> On this near-corner test set, total complex RMS is 32.95%, largely due to close-range dipole terms. An offline exact-LOS diagnostic reduces it to 4.44%; shadow-region error remains 33.08%. The independent Maxwell solvers agree to 0.23–0.33% globally. These figures describe different populations and must not be treated as universal error bounds.</p></div>
<h2>Side-by-side animation</h2><video controls preload="metadata" poster="previews/frame_0601.png" src="Sionna_vs_DiffeRT_Dielectric3D.mp4"></video><p>60 seconds · 1600 × 900 · 24 fps · <a href="Sionna_vs_DiffeRT_Dielectric3D.mp4">MP4</a> · <a href="Dielectric3D_Comparison.blend">Blender timeline</a> · <a href="video_validation.json">Decode/reopen verification</a>. White curves are independently solved Maxwell fields; colored curves are measured native or reciprocal engine channels. All modes are labelled. The material fix does not conceal the remaining dielectric error.</p>
{section}{controls}{result}{fix}{reproduction}</body></html>'''
    (out/'index.html').write_text(page,encoding='utf-8')
    print(out/'index.html')

if __name__=='__main__':main(Path(sys.argv[1]).resolve())
